      "country": "PL",
      "version": "challenge-planning-pl-en-v1-c29-draft",
      "author": "daily_author",
      "created_date": "2026-10-15",
      "reviewer": "daily_data_review",
      "learning_goal": "Identify fixed-amount periodic investing without a profit or emotion-control guarantee.",
      "copy": {
        "pl": {
          "id": "c7",
          "question": "Co opisuje DCA?",
          "answers": [
            {
              "id": "A",
              "text": "Kupowanie całej kwoty wyłącznie w najniższej cenie"
            },
            {
              "id": "B",
              "text": "Sprzedaż wszystkiego przy każdym spadku"
            },
            {
              "id": "C",
              "text": "Stała kwota w regularnych odstępach, niezależnie od ceny"
            },
            {
              "id": "D",
              "text": "Zamiana oszczędności na dolary"
            }
          ],
          "correctAnswer": "C",
          "explanation": "DCA oznacza równą kwotę w regularnych odstępach; niższa cena daje więcej jednostek. Nie gwarantuje zysku ani ochrony przed stratą i nie usuwa automatycznie emocji. Przykład bez opłat i podatku: 100 zł przy cenie 10 zł i 100 zł przy 20 zł to 15 jednostek. Przy cenie 8 zł są warte 120 zł wobec 200 zł wpłat. Wpłaty są dobrowolne, po podstawowych potrzebach i wymaganych minimalnych spłatach.",
          "reward": 50,
          "category": "Wyzwanie"
        },
        "en": {
          "id": "c7",
          "question": "Which statement describes DCA?",
          "answers": [
            {
              "id": "A",
              "text": "Investing the whole amount only at the lowest price"
            },
            {
              "id": "B",
              "text": "Selling everything after every decline"
            },
            {
              "id": "C",
              "text": "An equal amount at regular intervals, regardless of price"
            },
            {
              "id": "D",
              "text": "Converting savings into dollars"
            }
          ],
          "correctAnswer": "C",
          "explanation": "DCA uses an equal amount at regular intervals; a lower price buys more units. It guarantees neither profit nor protection from loss and does not automatically remove emotions. With no fees or tax: PLN 100 at 10 and PLN 100 at 20 buys 15 units. At 8 they are worth PLN 120 versus PLN 200 contributed. Contributions are optional, after essentials and required minimum repayments.",
          "reward": 50,
          "category": "Deep Dive"
        }
      },
      "source_ids": [
        "sec-dca",
        "sec-risk"
      ],
      "wrong_option_explanations": {
        "A": {
          "pl": "DCA nie zakłada trafienia w najniższą cenę; cena może dalej spadać.",
          "en": "DCA does not require identifying the lowest price; prices can keep falling."
        },
        "B": {
          "pl": "Automatyczna sprzedaż przy każdym spadku nie jest regularnym nabywaniem za równą kwotę.",
          "en": "Selling at every decline is not regular fixed-amount buying."
        },
        "D": {
          "pl": "Nazwa nie wymaga dolara ani zmiany waluty; przykład dotyczy PLN.",
          "en": "The name requires neither dollars nor currency conversion; this example uses PLN."
        }
      },
