        "price_path_hypothetical": true,
        "no_profit_or_loss_protection_guarantee": true,
        "contributions_optional_after_essentials_minimums": true
      }
    },
    {
      "id": "c8",
      "correctAnswer": "B",
      "reward": 50,
      "country": "PL",
      "version": "challenge-planning-pl-en-v1-c29-draft",
      "author": "daily_author",
      "created_date": "2026-10-15",
      "reviewer": "daily_data_review",
      "learning_goal": "Use rule72 only as an estimate under stated compounding assumptions.",
      "copy": {
        "pl": {
          "id": "c8",
          "question": "Reguła 72: hipotetyczne stałe dodatnie 8% nominalnie rocznie, kapitalizacja roczna, bez wpłat, wypłat, opłat i podatku; inflacja pominięta. Jaki szacunek czasu do podwojenia daje ta reguła?",
          "answers": [
            {
              "id": "A",
              "text": "Około 6 lat"
            },
            {
              "id": "B",
              "text": "Około 9 lat"
            },
            {
              "id": "C",
              "text": "Około 72 lat"
            },
            {
              "id": "D",
              "text": "Dokładnie 9 lat dla każdej inwestycji"
            }
          ],
          "correctAnswer": "B",
          "explanation": "72 ÷8 ≈ 9 lat to przybliżenie, nie dokładny termin. W podanym modelu 1 000 × 1,08⁹ ≈1 999,00 zł; po 10 rocznych dopisaniach jest ponad 2 000 zł. Stałe dodatnie 8% jest założeniem, nie prognozą. Rzeczywiste stopy mogą się zmieniać, a inwestycje tracić. To nominalny model bez przepływów, opłat, podatku i inflacji.",
          "reward": 50,
          "category": "Wyzwanie"
        },
        "en": {
          "id": "c8",
          "question": "Rule 72: a hypothetical constant positive 8% nominal annual rate, annual compounding, no contributions, withdrawals, fees or tax; inflation ignored. What doubling-time estimate does the rule give?",
          "answers": [
            {
              "id": "A",
              "text": "About 6 years"
            },
            {
              "id": "B",
              "text": "About 9 years"
            },
            {
              "id": "C",
              "text": "About 72 years"
            },
            {
              "id": "D",
              "text": "Exactly 9 years for every investment"
            }
          ],
          "correctAnswer": "B",
          "explanation": "72 ÷8 ≈ 9 years is an approximation, not an exact date. In the model, 1,000 × 1.08⁹ ≈ PLN 1,999.00; after 10 annual credits it exceeds PLN 2,000. A constant positive 8% is an assumption, not a forecast. Actual rates may change and investments can lose value. This nominal model excludes cash flows, fees, tax and inflation.",
          "reward": 50,
          "category": "Deep Dive"
        }
      },
      "source_ids": [
        "sec-compound"
      ],
      "wrong_option_explanations": {
        "A": {
          "pl": "72 podzielone przez 8 daje 9, nie 6.",
          "en": "72 divided by 8 is 9, not 6."
        },
        "C": {
          "pl": "72 jest licznikiem reguły, a nie wynikiem dla założonych 8%.",
          "en": "72 is the rule’s numerator, not the result at the assumed 8%."
        },
        "D": {
          "pl": "Reguła jest przybliżeniem, a model po 9 okresach jest jeszcze poniżej podwojenia. Nie gwarantuje wyniku każdej inwestycji.",
          "en": "The rule is approximate and this model is still below doubling after 9 periods. It guarantees no result for every investment."
        }
      },
      "calculation_assumptions": {
        "currency": "PLN",
        "initial": 1000,
        "constant_positive_nominal_annual_percent": 8,
        "annual_compounding": true,
        "contributions": 0,
        "withdrawals": 0,
        "fees": 0,
        "tax": 0,
        "inflation_ignored": true,
        "rule72_estimate_years": 9,
        "annual_periods_9_balance_exact": "1000*(1.08^9)",
        "annual_periods_9_balance_rounded": 1999,
        "annual_periods_10_balance_exact": "1000*(1.08^10)",
        "nominal_doubling_target": 2000,
        "first_integer_annual_period_above_target": 10,
        "approximation_not_forecast": true
      }
    },
