      "learning_goal": "Understand exchange trading separately from strategy, concentration and costs.",
      "copy": {
        "pl": {
          "id": "c9",
          "question": "Czym jest ETF?",
          "answers": [
            {
              "id": "A",
              "text": "Depozytem gwarantującym określone odsetki"
            },
            {
              "id": "B",
              "text": "Elektroniczną opłatą za przelew"
            },
            {
              "id": "C",
              "text": "Funduszem notowanym na giełdzie, indeksowym lub aktywnym"
            },
            {
              "id": "D",
              "text": "Państwową rezerwą awaryjną"
            }
          ],
          "correctAnswer": "C",
          "explanation": "ETF jest funduszem notowanym na giełdzie. Może śledzić indeks albo być zarządzany aktywnie. Dywersyfikacja zależy od rzeczywistego składu; fundusz wąskiego sektora może być skoncentrowany. Nazwa nie gwarantuje niskich kosztów ani braku strat. Sprawdź cel, skład, ryzyko i koszty; zakup nie jest wymagany.",
          "reward": 50,
          "category": "Wyzwanie"
        },
        "en": {
          "id": "c9",
          "question": "What is an ETF?",
          "answers": [
            {
              "id": "A",
              "text": "A deposit guaranteeing a stated interest payment"
            },
            {
              "id": "B",
              "text": "An electronic transfer fee"
            },
            {
              "id": "C",
              "text": "An exchange-traded fund, indexed or actively managed"
            },
            {
              "id": "D",
              "text": "A government emergency reserve"
            }
          ],
          "correctAnswer": "C",
          "explanation": "An ETF is an exchange-traded fund. It may track an index or be actively managed. Diversification depends on actual holdings; a narrow-sector fund can be concentrated. The label guarantees neither low costs nor freedom from loss. Check objectives, holdings, risks and costs; no purchase is required.",
          "reward": 50,
          "category": "Deep Dive"
        }
      },
      "source_ids": [
        "sec-etf",
        "sec-risk"
      ],
      "wrong_option_explanations": {
