    {
      "id": "c11",
      "correctAnswer": "B",
      "reward": 50,
      "country": "PL",
      "version": "challenge-planning-pl-en-v1-c29-draft",
      "author": "daily_author",
      "created_date": "2026-10-15",
      "reviewer": "daily_data_review",
      "learning_goal": "Distinguish fixed-coupon secondary prices from contract cash flows and default risk.",
      "copy": {
        "pl": {
          "id": "c11",
          "question": "Co zwykle dzieje się z ceną istniejącej obligacji o stałym kuponie na rynku wtórnym, gdy porównywalna rentowność rynkowa rośnie, a pozostałe warunki są takie same?",
          "answers": [
            {
              "id": "A",
              "text": "Cena rośnie"
            },
            {
              "id": "B",
              "text": "Cena spada"
            },
            {
              "id": "C",
              "text": "Cena zawsze pozostaje równa nominałowi"
            },
            {
              "id": "D",
              "text": "Cena musi się podwoić"
            }
          ],
